//! Test Mode's network load: generated bytes streamed both ways between the
//! primary and each computer of the show network while a test runs, so a
//! busy network (a large copy over the LAN during the 0.24.3 test pushed round
//! trips from 28 to 157 ms) can be had on purpose and compared with a run
//! without it.
//!
//! Nothing is read from or written to disk and nothing is downloaded: one
//! buffer of made-up bytes (`pattern`) is sent again and again. Each computer
//! has its own TCP connection to the primary (`LoadServer`, `LoadClient`),
//! apart from the hub's sessions (whose bounded queue must never fill), with
//! a paced writer thread (`Pacer`) and a reader thread that throws away what
//! it reads, on each side. The primary counts both ways itself (`Flow`), so
//! the computers report nothing about it.
//!
//! The primary starts it when a test begins playing (`testmode::fleet`) and
//! says where in `NetTest::Begin`'s `load` (a field an older NewQ ignores); a
//! computer dials it only while measuring for that test, and lets go at
//! `End`, when it leaves the network, or when it stops measuring. Any error
//! ends that connection with one line in the log, nothing more. Never on the
//! main thread: starting binds a listener (or spawns the dialling thread) and
//! stopping sets a flag and shuts the sockets, without waiting for a thread.

use crate::net::node::NodeId;
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::io::{Read, Write};
use std::net::{Shutdown, SocketAddr, TcpListener, TcpStream};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::{Duration, Instant};

/// How hard Test Mode loads the network (kept in `Prefs::test_load`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", from = "String")]
pub enum LoadLevel {
    /// No load (and a word from a later NewQ that this one doesn't know).
    #[default]
    Off,
    /// About 50 Mbit/s each way per computer.
    Light,
    /// About 400 Mbit/s each way per computer.
    Heavy,
    /// As fast as the network takes it.
    Full,
}

impl From<String> for LoadLevel {
    fn from(word: String) -> LoadLevel {
        match word.trim().to_lowercase().as_str() {
            "light" => LoadLevel::Light,
            "heavy" => LoadLevel::Heavy,
            "full" => LoadLevel::Full,
            _ => LoadLevel::Off,
        }
    }
}

impl LoadLevel {
    pub const ALL: [LoadLevel; 4] = [
        LoadLevel::Off,
        LoadLevel::Light,
        LoadLevel::Heavy,
        LoadLevel::Full,
    ];

    pub fn is_off(&self) -> bool {
        *self == LoadLevel::Off
    }

    /// Bytes a second each way per computer; None: no limit.
    pub fn bytes_per_sec(self) -> Option<u64> {
        match self {
            LoadLevel::Light => Some(50_000_000 / 8),
            LoadLevel::Heavy => Some(400_000_000 / 8),
            LoadLevel::Off | LoadLevel::Full => None,
        }
    }

    /// The window's words for it.
    pub fn label(self) -> &'static str {
        match self {
            LoadLevel::Off => "Off",
            LoadLevel::Light => "Light (about 50 Mbit/s)",
            LoadLevel::Heavy => "Heavy (about 400 Mbit/s)",
            LoadLevel::Full => "As fast as it goes",
        }
    }

    /// The report's words: "Heavy, about 400 Mbit/s each way per computer".
    pub fn describe(self) -> String {
        match self.bytes_per_sec() {
            Some(b) => format!(
                "{}, about {:.0} Mbit/s each way per computer",
                self.short(),
                mbit(b, 1.0)
            ),
            None if self.is_off() => "off".into(),
            None => "as fast as it goes, each way per computer".into(),
        }
    }

    pub fn short(self) -> &'static str {
        match self {
            LoadLevel::Off => "Off",
            LoadLevel::Light => "Light",
            LoadLevel::Heavy => "Heavy",
            LoadLevel::Full => "As fast as it goes",
        }
    }

    /// `NEWQ_TEST_LOAD` (light, heavy, full or off), for developers' runs
    /// (`NEWQ_NET_TEST_AUTOSTART`); it wins over the window's choice.
    pub fn from_env() -> Option<LoadLevel> {
        std::env::var("NEWQ_TEST_LOAD").ok().map(LoadLevel::from)
    }
}

/// Megabits a second for `bytes` over `secs`.
pub fn mbit(bytes: u64, secs: f64) -> f64 {
    if secs <= 0.0 {
        return 0.0;
    }
    bytes as f64 * 8.0 / 1_000_000.0 / secs
}

/// Where a computer finds the primary's load (in `NetTest::Begin`).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct LoadAsk {
    /// The port at the primary's address.
    pub port: u16,
    /// Said first on the connection, with the computer's id (a stranger on
    /// the LAN can't make the primary send).
    pub token: u64,
    /// Each way; None: as fast as it goes.
    #[serde(default)]
    pub bytes_per_sec: Option<u64>,
}

// ----- Pacing (pure) -------------------------------------------------------------

/// Unused time is saved up for at most this long (s), so a pause isn't
/// followed by a burst.
pub const CREDIT: f64 = 0.25;

/// Spaces bytes out to a rate. Times are seconds from any fixed start.
#[derive(Clone, Debug)]
pub struct Pacer {
    rate: Option<u64>,
    /// When the bytes taken so far are paid for.
    paid_until: Option<f64>,
}

impl Pacer {
    pub fn new(bytes_per_sec: Option<u64>) -> Pacer {
        Pacer {
            rate: bytes_per_sec.map(|r| r.max(1)),
            paid_until: None,
        }
    }

    /// `n` bytes are to go at time `now`: how long to wait first (s).
    pub fn take(&mut self, now: f64, n: u64) -> f64 {
        let Some(rate) = self.rate else {
            return 0.0;
        };
        let start = self.paid_until.map_or(now, |p| p.max(now - CREDIT));
        self.paid_until = Some(start + n as f64 / rate as f64);
        (start - now).max(0.0)
    }
}

// ----- What went -------------------------------------------------------------------

/// The bytes that went each way with one computer (counted by the primary).
#[derive(Debug, Default)]
pub struct Flow {
    pub sent: AtomicU64,
    pub received: AtomicU64,
    /// Milliseconds from the server's start: the first connection, and the
    /// last time either way moved or a connection ended.
    first_ms: AtomicU64,
    last_ms: AtomicU64,
    /// Connections up now.
    live: AtomicU64,
}

/// One computer's figures for the report.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Totals {
    pub sent: u64,
    pub received: u64,
    /// From its first connection to the last of it (s).
    pub secs: f64,
    pub connected: bool,
}

impl Totals {
    pub fn mbit_out(&self) -> f64 {
        mbit(self.sent, self.secs)
    }
    pub fn mbit_in(&self) -> f64 {
        mbit(self.received, self.secs)
    }
}

/// "to it 1234 MB (avg 398.2 Mbit/s), from it 1200 MB (avg 387.1 Mbit/s) over 31 s".
pub fn totals_words(t: &Totals) -> String {
    format!(
        "to it {} (avg {:.1} Mbit/s), from it {} (avg {:.1} Mbit/s) over {:.0} s",
        mb(t.sent),
        t.mbit_out(),
        mb(t.received),
        t.mbit_in(),
        t.secs
    )
}

fn mb(b: u64) -> String {
    format!("{:.1} MB", b as f64 / 1_000_000.0)
}

/// The report's lines: whether the load was on, and what went with each
/// computer (`names` with their figures; None: it never connected).
pub fn report_lines(level: LoadLevel, each: &[(String, Option<Totals>)]) -> Vec<String> {
    if level.is_off() {
        return vec![
            "Network load: off (Test Mode ▸ More ▸ Load the network while testing, to compare)."
                .into(),
        ];
    }
    let mut v = vec![format!(
        "Network load: on, {} (generated bytes, both ways, on a connection of its own).",
        level.describe()
    )];
    let (mut out, mut inn) = (0u64, 0u64);
    for (name, t) in each {
        match t {
            Some(t) => {
                out += t.sent;
                inn += t.received;
                v.push(format!("  {name}: {}", totals_words(t)));
            }
            None => v.push(format!(
                "  {name}: never connected for the load (an older NewQ there, or a firewall in the way); nothing went."
            )),
        }
    }
    if each.len() > 1 {
        v.push(format!("  Altogether: {} out, {} in.", mb(out), mb(inn)));
    }
    v
}

// ----- The bytes -------------------------------------------------------------------

/// Bytes per write.
const CHUNK: usize = 64 * 1024;
/// A write that can't go for this long ends the connection.
const WRITE_PATIENCE: Duration = Duration::from_secs(10);
/// Reads wake this often to look at the stop flag.
const READ_STEP: Duration = Duration::from_millis(200);
/// The first words on a connection: the token and the computer's id.
const HELLO: usize = 16;
/// Dialling gives up after this long.
const DIAL_PATIENCE: Duration = Duration::from_secs(5);

/// The made-up bytes sent (a fixed pseudo-random pattern, made once).
fn pattern() -> &'static [u8] {
    static P: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
    P.get_or_init(|| {
        let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
        (0..CHUNK)
            .map(|_| {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                (x >> 24) as u8
            })
            .collect()
    })
}

/// Sleep `secs` in short steps; false if `stop` was set meanwhile.
fn wait(secs: f64, stop: &AtomicBool, done: &AtomicBool) -> bool {
    let until = Instant::now() + Duration::from_secs_f64(secs.min(5.0));
    loop {
        if stop.load(Ordering::Relaxed) || done.load(Ordering::Relaxed) {
            return false;
        }
        let now = Instant::now();
        if now >= until {
            return true;
        }
        std::thread::sleep((until - now).min(Duration::from_millis(50)));
    }
}

/// Counters a side bumps as bytes go.
struct Counts {
    flow: Arc<Flow>,
    base: Instant,
}

impl Counts {
    fn touch(&self) {
        let ms = self.base.elapsed().as_millis() as u64;
        self.flow.last_ms.fetch_max(ms, Ordering::Relaxed);
    }
}

/// Run one connection both ways until it fails or `stop`: a paced writer
/// thread and the reader here. Logs one line at its end.
fn run_link(
    stream: TcpStream,
    rate: Option<u64>,
    stop: Arc<AtomicBool>,
    counts: Counts,
    who: String,
) {
    let done = Arc::new(AtomicBool::new(false));
    let _ = stream.set_nodelay(true);
    let _ = stream.set_write_timeout(Some(WRITE_PATIENCE));
    let _ = stream.set_read_timeout(Some(READ_STEP));
    let flow = counts.flow.clone();
    flow.live.fetch_add(1, Ordering::Relaxed);
    let first = counts.base.elapsed().as_millis() as u64;
    let _ = flow
        .first_ms
        .compare_exchange(0, first.max(1), Ordering::Relaxed, Ordering::Relaxed);
    counts.touch();
    let why_out: Arc<Mutex<Option<String>>> = Arc::new(Mutex::new(None));
    let writer = match stream.try_clone() {
        Ok(mut w) => {
            let (stop, done, flow, why) =
                (stop.clone(), done.clone(), flow.clone(), why_out.clone());
            std::thread::Builder::new()
                .name("net-load-out".into())
                .spawn(move || {
                    let mut pacer = Pacer::new(rate);
                    let t0 = Instant::now();
                    let buf = pattern();
                    let reason = loop {
                        let w8 = pacer.take(t0.elapsed().as_secs_f64(), buf.len() as u64);
                        if w8 > 0.0 && !wait(w8, &stop, &done) {
                            break None;
                        }
                        if stop.load(Ordering::Relaxed) || done.load(Ordering::Relaxed) {
                            break None;
                        }
                        if let Err(e) = w.write_all(buf) {
                            break Some(format!("sending: {e}"));
                        }
                        flow.sent.fetch_add(buf.len() as u64, Ordering::Relaxed);
                    };
                    *why.lock() = reason;
                    done.store(true, Ordering::Relaxed);
                    let _ = w.shutdown(Shutdown::Both);
                })
                .is_ok()
        }
        Err(_) => false,
    };
    let mut r = stream;
    let mut buf = vec![0u8; CHUNK];
    let mut why: Option<String> = if writer {
        None
    } else {
        Some("no thread to send".into())
    };
    let mut quiet = Instant::now();
    while why.is_none() {
        if stop.load(Ordering::Relaxed) || done.load(Ordering::Relaxed) {
            break;
        }
        match r.read(&mut buf) {
            Ok(0) => why = Some("the other side closed it".into()),
            Ok(n) => {
                flow.received.fetch_add(n as u64, Ordering::Relaxed);
                if quiet.elapsed() >= Duration::from_millis(200) {
                    quiet = Instant::now();
                    counts.touch();
                }
            }
            Err(e)
                if matches!(
                    e.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) => {}
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {}
            Err(e) => why = Some(format!("receiving: {e}")),
        }
    }
    done.store(true, Ordering::Relaxed);
    let _ = r.shutdown(Shutdown::Both);
    counts.touch();
    flow.live.fetch_sub(1, Ordering::Relaxed);
    let why = why
        .or_else(|| why_out.lock().clone())
        .unwrap_or_else(|| "the test ended".into());
    log::info!(
        "network load with {who} ended ({why}): {} sent, {} received",
        mb(flow.sent.load(Ordering::Relaxed)),
        mb(flow.received.load(Ordering::Relaxed))
    );
}

// ----- The primary -----------------------------------------------------------------

/// The primary's side: a listener the computers dial, a connection each.
pub struct LoadServer {
    ask: LoadAsk,
    stop: Arc<AtomicBool>,
    flows: Arc<Mutex<BTreeMap<NodeId, Arc<Flow>>>>,
    /// Each connection (to cut it at once on `stop` or when a computer goes).
    streams: Arc<Mutex<Vec<(NodeId, TcpStream)>>>,
    base: Instant,
    /// The last look at the counters, for the rate now.
    looked: Mutex<Option<Looked>>,
}

/// When the counters were last looked at, what they were, and the rates
/// worked out then (Mbit/s out and in).
type Looked = (
    Instant,
    HashMap<NodeId, (u64, u64)>,
    HashMap<NodeId, (f64, f64)>,
);

impl LoadServer {
    /// Listen on `bind` (port 0 picks one) for `level`.
    pub fn start(bind: SocketAddr, level: LoadLevel) -> Result<LoadServer, String> {
        let listener = TcpListener::bind(bind).map_err(|e| e.to_string())?;
        listener.set_nonblocking(true).map_err(|e| e.to_string())?;
        let port = listener.local_addr().map_err(|e| e.to_string())?.port();
        let ask = LoadAsk {
            port,
            token: crate::net::node::random_u64(),
            bytes_per_sec: level.bytes_per_sec(),
        };
        let server = LoadServer {
            ask: ask.clone(),
            stop: Arc::new(AtomicBool::new(false)),
            flows: Arc::default(),
            streams: Arc::default(),
            base: Instant::now(),
            looked: Mutex::new(None),
        };
        let (stop, flows, streams, base) = (
            server.stop.clone(),
            server.flows.clone(),
            server.streams.clone(),
            server.base,
        );
        std::thread::Builder::new()
            .name("net-load".into())
            .spawn(move || accept_loop(listener, ask, stop, flows, streams, base))
            .map_err(|e| e.to_string())?;
        log::info!(
            "network load: listening on port {port}, {}",
            level.describe()
        );
        Ok(server)
    }

    /// What the computers are told (in `NetTest::Begin`).
    pub fn ask(&self) -> LoadAsk {
        self.ask.clone()
    }

    /// Stop every connection (at once; nothing is waited for).
    pub fn stop(&self) {
        if self.stop.swap(true, Ordering::Relaxed) {
            return;
        }
        for (_, s) in self.streams.lock().drain(..) {
            let _ = s.shutdown(Shutdown::Both);
        }
    }

    /// Cut the connections of computers not among `ids` (gone from the network).
    pub fn keep_only(&self, ids: &[NodeId]) {
        self.streams.lock().retain(|(id, s)| {
            let keep = ids.contains(id);
            if !keep {
                let _ = s.shutdown(Shutdown::Both);
            }
            keep
        });
    }

    /// Each computer's figures so far (those that ever connected).
    pub fn totals(&self) -> BTreeMap<NodeId, Totals> {
        let now = self.base.elapsed().as_millis() as u64;
        self.flows
            .lock()
            .iter()
            .map(|(id, f)| {
                let live = f.live.load(Ordering::Relaxed) > 0;
                let first = f.first_ms.load(Ordering::Relaxed);
                let last = if live {
                    now
                } else {
                    f.last_ms.load(Ordering::Relaxed)
                };
                (
                    *id,
                    Totals {
                        sent: f.sent.load(Ordering::Relaxed),
                        received: f.received.load(Ordering::Relaxed),
                        secs: last.saturating_sub(first) as f64 / 1000.0,
                        connected: live,
                    },
                )
            })
            .collect()
    }

    /// The rate each way with each computer now (Mbit/s, out and in), over
    /// about the last second or two.
    pub fn rates(&self) -> HashMap<NodeId, (f64, f64)> {
        let now = Instant::now();
        let counts: HashMap<NodeId, (u64, u64)> = self
            .flows
            .lock()
            .iter()
            .map(|(id, f)| {
                (
                    *id,
                    (
                        f.sent.load(Ordering::Relaxed),
                        f.received.load(Ordering::Relaxed),
                    ),
                )
            })
            .collect();
        let mut looked = self.looked.lock();
        match looked.as_mut() {
            Some((at, before, rates)) => {
                let secs = now.duration_since(*at).as_secs_f64();
                if secs >= 1.0 {
                    *rates = counts
                        .iter()
                        .map(|(id, (s, r))| {
                            let (s0, r0) = before.get(id).copied().unwrap_or((0, 0));
                            (
                                *id,
                                (
                                    mbit(s.saturating_sub(s0), secs),
                                    mbit(r.saturating_sub(r0), secs),
                                ),
                            )
                        })
                        .collect();
                    *at = now;
                    *before = counts;
                }
                rates.clone()
            }
            None => {
                *looked = Some((now, counts, HashMap::new()));
                HashMap::new()
            }
        }
    }
}

impl Drop for LoadServer {
    fn drop(&mut self) {
        self.stop();
    }
}

fn accept_loop(
    listener: TcpListener,
    ask: LoadAsk,
    stop: Arc<AtomicBool>,
    flows: Arc<Mutex<BTreeMap<NodeId, Arc<Flow>>>>,
    streams: Arc<Mutex<Vec<(NodeId, TcpStream)>>>,
    base: Instant,
) {
    while !stop.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((s, from)) => {
                let (ask, stop, flows, streams) =
                    (ask.clone(), stop.clone(), flows.clone(), streams.clone());
                let _ = std::thread::Builder::new()
                    .name("net-load-in".into())
                    .spawn(move || serve(s, from, ask, stop, flows, streams, base));
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                std::thread::sleep(Duration::from_millis(50));
            }
            Err(e) => {
                log::info!("network load: no more connections ({e})");
                break;
            }
        }
    }
}

fn serve(
    mut s: TcpStream,
    from: SocketAddr,
    ask: LoadAsk,
    stop: Arc<AtomicBool>,
    flows: Arc<Mutex<BTreeMap<NodeId, Arc<Flow>>>>,
    streams: Arc<Mutex<Vec<(NodeId, TcpStream)>>>,
    base: Instant,
) {
    let _ = s.set_nonblocking(false);
    let _ = s.set_read_timeout(Some(DIAL_PATIENCE));
    let mut hello = [0u8; HELLO];
    if s.read_exact(&mut hello).is_err() {
        return;
    }
    let token = u64::from_be_bytes(hello[..8].try_into().expect("8 bytes"));
    let id = NodeId(u64::from_be_bytes(hello[8..].try_into().expect("8 bytes")));
    if token != ask.token {
        log::info!("network load: a connection from {from} without the test's token, closed");
        return;
    }
    if stop.load(Ordering::Relaxed) {
        return;
    }
    match s.try_clone() {
        Ok(c) => streams.lock().push((id, c)),
        Err(_) => return,
    }
    let flow = flows.lock().entry(id).or_default().clone();
    log::info!("network load: {} ({from}) connected", id.short());
    run_link(
        s,
        ask.bytes_per_sec,
        stop,
        Counts { flow, base },
        format!("{} ({from})", id.short()),
    );
}

// ----- A computer ------------------------------------------------------------------

/// A computer's side: one connection to the primary, for one test run.
pub struct LoadClient {
    run: u64,
    stop: Arc<AtomicBool>,
    ended: Arc<AtomicBool>,
    stream: Arc<Mutex<Option<TcpStream>>>,
    flow: Arc<Flow>,
}

impl LoadClient {
    /// Dial the primary at `addr` (on a thread of its own) for test `run`.
    pub fn start(addr: SocketAddr, me: NodeId, run: u64, ask: &LoadAsk) -> LoadClient {
        let c = LoadClient {
            run,
            stop: Arc::new(AtomicBool::new(false)),
            ended: Arc::new(AtomicBool::new(false)),
            stream: Arc::default(),
            flow: Arc::default(),
        };
        let (stop, ended, stream, flow) = (
            c.stop.clone(),
            c.ended.clone(),
            c.stream.clone(),
            c.flow.clone(),
        );
        let (token, rate) = (ask.token, ask.bytes_per_sec);
        let spawned = std::thread::Builder::new()
            .name("net-load-dial".into())
            .spawn(move || {
                match TcpStream::connect_timeout(&addr, DIAL_PATIENCE) {
                    Ok(mut s) => {
                        let mut hello = [0u8; HELLO];
                        hello[..8].copy_from_slice(&token.to_be_bytes());
                        hello[8..].copy_from_slice(&me.0.to_be_bytes());
                        let _ = s.set_write_timeout(Some(DIAL_PATIENCE));
                        if let Err(e) = s.write_all(&hello) {
                            log::info!("network load: couldn't start with the primary at {addr}: {e}");
                        } else if let Ok(c) = s.try_clone() {
                            *stream.lock() = Some(c);
                            // Stopped while dialling.
                            if stop.load(Ordering::Relaxed) {
                                let _ = s.shutdown(Shutdown::Both);
                            } else {
                                log::info!("network load: sending to and receiving from the primary at {addr}");
                                run_link(
                                    s,
                                    rate,
                                    stop,
                                    Counts {
                                        flow,
                                        base: Instant::now(),
                                    },
                                    format!("the primary ({addr})"),
                                );
                            }
                        }
                    }
                    Err(e) => {
                        log::info!("network load: couldn't reach the primary at {addr}: {e}");
                    }
                }
                ended.store(true, Ordering::Relaxed);
            })
            .is_ok();
        if !spawned {
            c.ended.store(true, Ordering::Relaxed);
        }
        c
    }

    pub fn run(&self) -> u64 {
        self.run
    }

    /// Its connection is over (or never came).
    pub fn ended(&self) -> bool {
        self.ended.load(Ordering::Relaxed)
    }

    /// Bytes sent and received so far.
    #[cfg(test)]
    pub fn counts(&self) -> (u64, u64) {
        (
            self.flow.sent.load(Ordering::Relaxed),
            self.flow.received.load(Ordering::Relaxed),
        )
    }

    /// Let go (at once; the threads end by themselves).
    pub fn stop(&self) {
        self.stop.store(true, Ordering::Relaxed);
        if let Some(s) = self.stream.lock().take() {
            let _ = s.shutdown(Shutdown::Both);
        }
    }
}

impl Drop for LoadClient {
    fn drop(&mut self) {
        self.stop();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_pacer_keeps_to_its_rate_and_saves_up_only_a_quarter_second() {
        // 1 MB/s, 100 KB at a time.
        let mut p = Pacer::new(Some(1_000_000));
        let mut t = 0.0;
        let mut sent = 0u64;
        // Taking as fast as allowed for ten seconds sends ten megabytes.
        while t < 10.0 {
            t += p.take(t, 100_000);
            sent += 100_000;
        }
        assert!((sent as f64 - 10_000_000.0).abs() <= 200_000.0, "{sent}");
        // The first goes at once; the next waits its turn.
        let mut p = Pacer::new(Some(1_000_000));
        assert_eq!(p.take(5.0, 500_000), 0.0);
        assert!((p.take(5.0, 500_000) - 0.5).abs() < 1e-9);
        // After a long pause, no burst: at most a quarter second's credit.
        let mut p = Pacer::new(Some(1_000_000));
        p.take(0.0, 1_000);
        let mut burst = 0u64;
        while p.take(100.0, 10_000) == 0.0 {
            burst += 10_000;
        }
        assert!(burst <= 270_000, "{burst}");
        // No limit: never waits.
        let mut p = Pacer::new(None);
        for _ in 0..1000 {
            assert_eq!(p.take(0.0, u64::MAX / 2000), 0.0);
        }
    }

    #[test]
    fn the_levels_rates_words_and_file_form() {
        assert_eq!(LoadLevel::Light.bytes_per_sec(), Some(6_250_000));
        assert_eq!(LoadLevel::Heavy.bytes_per_sec(), Some(50_000_000));
        assert_eq!(LoadLevel::Full.bytes_per_sec(), None);
        assert_eq!(
            LoadLevel::Heavy.describe(),
            "Heavy, about 400 Mbit/s each way per computer"
        );
        assert_eq!(serde_json::to_string(&LoadLevel::Full).unwrap(), "\"full\"");
        // A word from a later NewQ is Off, not a failure to read the file.
        assert_eq!(
            serde_json::from_str::<LoadLevel>("\"tidal\"").unwrap(),
            LoadLevel::Off
        );
        assert!((mbit(6_250_000, 1.0) - 50.0).abs() < 1e-9);
        assert_eq!(mbit(10, 0.0), 0.0);
    }

    #[test]
    fn the_report_says_whether_it_was_on_and_what_went_each_way() {
        assert_eq!(
            report_lines(LoadLevel::Off, &[("Left".into(), None)]),
            vec![
                "Network load: off (Test Mode ▸ More ▸ Load the network while testing, to compare)."
                    .to_string()
            ]
        );
        let t = Totals {
            sent: 125_000_000,
            received: 62_500_000,
            secs: 20.0,
            connected: false,
        };
        let v = report_lines(
            LoadLevel::Light,
            &[("Left".into(), Some(t)), ("Right".into(), None)],
        );
        assert_eq!(
            v,
            vec![
                "Network load: on, Light, about 50 Mbit/s each way per computer (generated bytes, both ways, on a connection of its own).".to_string(),
                "  Left: to it 125.0 MB (avg 50.0 Mbit/s), from it 62.5 MB (avg 25.0 Mbit/s) over 20 s".into(),
                "  Right: never connected for the load (an older NewQ there, or a firewall in the way); nothing went.".into(),
                "  Altogether: 125.0 MB out, 62.5 MB in.".into(),
            ]
        );
    }

    fn until(what: &str, f: impl Fn() -> bool) {
        let t = Instant::now();
        while !f() {
            assert!(t.elapsed() < Duration::from_secs(20), "{what}");
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    #[test]
    fn bytes_go_both_ways_at_the_rate_and_stop_when_asked() {
        let server = LoadServer::start("127.0.0.1:0".parse().unwrap(), LoadLevel::Light).unwrap();
        let ask = server.ask();
        let addr: SocketAddr = format!("127.0.0.1:{}", ask.port).parse().unwrap();
        // A stranger without the token gets nothing.
        let mut stranger = TcpStream::connect(addr).unwrap();
        stranger.write_all(&[0u8; HELLO]).unwrap();
        stranger
            .set_read_timeout(Some(Duration::from_secs(5)))
            .unwrap();
        let mut b = [0u8; 16];
        assert!(matches!(stranger.read(&mut b), Ok(0) | Err(_)), "closed");
        let client = LoadClient::start(addr, NodeId(7), 1, &ask);
        until("both ways", || {
            server
                .totals()
                .get(&NodeId(7))
                .is_some_and(|t| t.sent > 1_000_000 && t.received > 1_000_000)
        });
        let _ = server.rates();
        std::thread::sleep(Duration::from_millis(1500));
        let t = server.totals()[&NodeId(7)].clone();
        assert!(t.connected);
        // At about 50 Mbit/s: well under a gigabit after a second and a half.
        assert!(t.mbit_out() < 90.0 && t.mbit_out() > 10.0, "{t:?}");
        let (out, inn) = server.rates()[&NodeId(7)];
        assert!(
            out > 10.0 && out < 90.0 && inn > 10.0 && inn < 90.0,
            "{out} {inn}"
        );
        assert!(server.totals().len() == 1, "the stranger isn't counted");
        // Stopping ends the computer's side too.
        server.stop();
        until("the computer let go", || client.ended());
        until("not connected", || !server.totals()[&NodeId(7)].connected);
        let (s, r) = client.counts();
        assert!(s > 0 && r > 0);
    }

    #[test]
    fn a_computer_letting_go_or_dialling_nothing_just_ends() {
        let server = LoadServer::start("127.0.0.1:0".parse().unwrap(), LoadLevel::Full).unwrap();
        let ask = server.ask();
        let addr: SocketAddr = format!("127.0.0.1:{}", ask.port).parse().unwrap();
        let client = LoadClient::start(addr, NodeId(3), 1, &ask);
        until("going", || {
            server
                .totals()
                .get(&NodeId(3))
                .is_some_and(|t| t.received > 0)
        });
        drop(client);
        until("the primary saw it go", || {
            !server.totals()[&NodeId(3)].connected
        });
        // Cut by the primary when the computer leaves the network.
        let client = LoadClient::start(addr, NodeId(4), 1, &ask);
        until("going", || {
            server.totals().get(&NodeId(4)).is_some_and(|t| t.sent > 0)
        });
        server.keep_only(&[NodeId(3)]);
        until("cut", || client.ended());
        // Nothing listening: it ends by itself.
        drop(server);
        let gone = LoadClient::start("127.0.0.1:1".parse().unwrap(), NodeId(5), 1, &ask);
        until("ended", || gone.ended());
    }
}
